<?php declare(strict_types=1);echo$view->render('components.page-hero',compact('page','e'));?><section class="section"><div class="container-wide"><div class="feature-grid feature-grid-three"><?php foreach($posts as$post):?><article class="feature-card"><p class="eyebrow"><?= $e(date('j M Y',strtotime($post['published_at']))) ?></p><h2><?= $e($post['title']) ?></h2><p><?= $e($post['excerpt']??'') ?></p><a href="/<?= $e($postType==='announcement'?'announcements':$postType) ?>/<?= rawurlencode($post['slug']) ?>">Read more</a></article><?php endforeach;?></div><?php if($posts===[]):?><div class="empty-state"><p>No published <?= $e($postType) ?> items are available.</p></div><?php endif;?></div></section>
